# repro/check_manifest.R -- is every appendix file accounted for, made by the
# producer the manifest names, and regenerated by this run?  Sourced by
# run_checks.R.
#
# manifest.csv columns
#   file         path relative to Supplementary/ (tables/x.csv, figures/y.png)
#   producer     Scripts/N_*.R | qmd:<chunk-label> | hmsc_converge/04_*.R
#   where        script section / chunk part that writes it (free text)
#   sections     appendix section(s) that show it ("-" if not shown)
#   role         shown | input (read only by a build chunk) | unused (tracked, not referenced)
#   exception    non-empty = known, documented reproducibility exception

qmd_refs <- function(qmd_lines) {
  hits <- regmatches(qmd_lines, gregexpr("(tables|figures)/[A-Za-z0-9_./-]+\\.(csv|png|jpg|pdf)", qmd_lines))
  sort(unique(unlist(hits)))
}

# All lines of one labelled chunk in the qmd.
chunk_text <- function(qmd_lines, label) {
  open <- grep(sprintf("^```\\{r %s\\}$", label), qmd_lines)
  if (length(open) != 1) return(character(0))
  close <- grep("^```$", qmd_lines); close <- close[close > open][1]
  qmd_lines[(open + 1):(close - 1)]
}

producer_code <- function(repo, qmd_lines, producer) {
  if (startsWith(producer, "qmd:")) return(chunk_text(qmd_lines, sub("^qmd:", "", producer)))
  f <- file.path(repo, producer)
  if (file.exists(f)) readLines(f, warn = FALSE) else character(0)
}

# Pointer stubs: chunks labelled *-source carry "# Source :" and "# Output :"
# lines (Output may continue on following "#   " lines).
parse_stubs <- function(qmd_lines) {
  labs <- sub("^```\\{r ([A-Za-z0-9_-]+-source)\\}$", "\\1",
              grep("^```\\{r [A-Za-z0-9_-]+-source\\}$", qmd_lines, value = TRUE))
  do.call(rbind, lapply(labs, function(l) {
    tx <- chunk_text(qmd_lines, l)
    src <- sub("^# *Source *: *", "", grep("^# *Source *:", tx, value = TRUE))
    src <- sub("[ ,].*$", "", src)
    i <- grep("^# *Output *:", tx)
    out_lines <- character(0)
    if (length(i)) {
      j <- i[1]; out_lines <- tx[j]
      while (j < length(tx) && grepl("^#\\s{3,}", tx[j + 1])) { j <- j + 1; out_lines <- c(out_lines, tx[j]) }
    }
    files <- unique(unlist(regmatches(out_lines,
               gregexpr("(tables|figures)/[A-Za-z0-9_./-]+\\.(csv|png|jpg|pdf)", out_lines))))
    if (!length(files)) files <- NA_character_
    data.frame(stub = l, source = if (length(src)) src[1] else NA, file = files)
  }))
}

check_manifest <- function(repo, cmp) {
  qmd_lines <- readLines(file.path(repo, "Supplementary/Supplementary_Appendix.qmd"), warn = FALSE)
  man <- utils::read.csv(file.path(repo, "repro/manifest.csv"), stringsAsFactors = FALSE,
                         na.strings = "")
  refs <- qmd_refs(qmd_lines)
  tracked <- sub("^Supplementary/", "", system2("git", c("-C", repo, "ls-files",
               "Supplementary/tables", "Supplementary/figures"), stdout = TRUE))
  res <- list()
  add <- function(file, check, status, detail = "")
    res[[length(res) + 1]] <<- data.frame(file = file, check = check, status = status, detail = detail)

  for (f in setdiff(union(refs, tracked), man$file))
    add(f, "in_manifest", "FAIL", if (f %in% refs) "referenced by the qmd, no manifest row" else "tracked, no manifest row")
  for (f in setdiff(man$file, union(refs, tracked)))
    add(f, "in_manifest", "FAIL", "manifest row for a file that is neither referenced nor tracked")
  dup <- man$file[duplicated(man$file)]
  for (f in dup) add(f, "single_producer", "FAIL", "listed twice in the manifest")

  app <- cmp[cmp$set == "appendix", ]
  app$rel <- sub("^Supplementary/", "", app$file)
  for (k in seq_len(nrow(man))) {
    m <- man[k, ]
    # role must agree with the qmd
    shown <- m$file %in% refs
    if (m$role == "shown" && !shown) add(m$file, "role", "FAIL", "role=shown but the qmd does not reference it")
    if (m$role != "shown" && shown && m$role != "input") add(m$file, "role", "FAIL", "referenced by the qmd but role != shown")
    # the producer's code must name the file
    code <- producer_code(repo, qmd_lines, m$producer)
    if (!length(code)) add(m$file, "producer_exists", "FAIL", paste("producer not found:", m$producer))
    else if (!any(grepl(basename(m$file), code, fixed = TRUE)) &&
             !any(grepl(tools::file_path_sans_ext(basename(m$file)), code, fixed = TRUE)))
      add(m$file, "producer_names_file", "FAIL", paste(m$producer, "never mentions", basename(m$file)))
    else add(m$file, "producer_names_file", "PASS", m$producer)
    # regenerated by this run?
    a <- app[app$rel == m$file, ]
    if (!nrow(a)) next
    st <- if (isTRUE(a$regenerated[1])) "PASS" else if (!is.na(m$exception)) "EXCEPTION" else "FAIL"
    add(m$file, "regenerated", st, if (st == "PASS") a$status[1] else
        if (st == "EXCEPTION") m$exception else "file not rewritten during this run")
  }

  stubs <- parse_stubs(qmd_lines)
  if (is.null(stubs) || !nrow(stubs)) {
    add("-", "pointer_stubs", "INFO", "no *-source pointer chunks in the qmd yet")
  } else {
    # A script may be pointed to from several sections (script 6 serves 5, 7.1
    # and 7.2), so: each stub may list only files its source writes, and the
    # stubs naming one source must together list every file it writes.
    for (s in unique(stubs$stub)) {
      st <- stubs[stubs$stub == s, ]
      extra <- setdiff(na.omit(st$file), man$file[man$producer == st$source[1]])
      add(s, "pointer_stub_outputs", if (!length(extra)) "PASS" else "FAIL",
          if (length(extra)) sprintf("source %s does not write: %s", st$source[1],
                                     paste(extra, collapse = ", ")) else st$source[1])
    }
    for (src in unique(stubs$source)) {
      miss <- setdiff(man$file[man$producer == src], na.omit(stubs$file[stubs$source == src]))
      add(src, "pointer_stub_coverage", if (!length(miss)) "PASS" else "FAIL",
          if (length(miss)) paste("written but listed in no stub:", paste(miss, collapse = ", ")) else "")
    }
    covered <- unique(stubs$source)
    script_prod <- unique(man$producer[!startsWith(man$producer, "qmd:") & man$role == "shown"])
    for (p in setdiff(script_prod, covered))
      add(p, "pointer_stub_exists", "FAIL", "script-produced files are shown but no *-source stub names this script")
  }
  do.call(rbind, res)
}
